; =====================================================================
;  TITLE.ASM -- the title screen (T-REL-1, D46; sunset T-REL-4, D70)
;
;  Shown at start-up and after the demo: a sunset over the sea after
;  Rube's reference picture.  "Acadia" in pale gold at the top left, a
;  sky in bands of colour with dark cloud streaks, a black island with
;  the game's fort, the sun (player 3) setting to its right, a glitter
;  path on the water and REBUILD at the bottom right.  The graphics,
;  font and colour tables are generated by tools/mktitle.py
;  (TITLE_GFX.ASM).
;
;  A DLI on the last blank line runs TT_DLI, which sets COLBK, COLPF0
;  and COLPF1 every second scan line for the whole picture; ST_VBI
;  (STATUS.ASM) points VDSLST at it while GSTATE is GS_TITLE.  Each
;  frame TT_ANIM sinks the sun a little (one P/M line every 256
;  frames), scatters new glitter on the water every TT_GRT frames and,
;  after TT_PSEC seconds with nothing touched, shows PRESS FIRE.
;
;  The title tune plays.  Fire, START or any key, once everything has
;  been let go, goes on to the setup screen, with the tune still
;  playing.  Left alone for DM_IDLE seconds, it plays the demo
;  (DEMO.ASM), which comes back here.
;
;  Its display list, TDLIST, sits in DLIST's page like SUDLIST.  The
;  water and the prompt are built in the map's screen memory (MAPSCR),
;  which the setup screen clears and the game redraws.
; =====================================================================

GS_TITLE = 5            ; GSTATE while the title screen is up
                        ; TITLEGFX, TTFONTA: MEM_A800.ASM / MEM_5200.ASM

; the picture's layout and glitter characters: as tools/mktitle.py
; makes them (TITLE_GFX.ASM's header lists the values)
TT_NL   =  96           ; colour table entries, 2 scan lines each
TT_WROWS = 3            ; mode 4 rows of water
TT_HORL =  144          ; the horizon: the picture's first water line
TT_SCOL =  35           ; the sun's character column (glitter path)
TG_SUN  =  11           ; gold glitter characters
TG_NSUN =  4
TG_BRT  =  15           ; bright glitter (inverse: PF3)
TG_NBRT =  2
TG_SKY  =  17           ; dim reflections of the sky (PF0)
TG_NSKY =  2

TT_SCR  =  MAPSCR       ; water: TT_WROWS mode 4 rows of 40, then the
TT_PRSO =  40*TT_WROWS  ; mode 6 prompt row (20) at this offset
TT_PSEC =  10           ; idle seconds before PRESS FIRE shows
TT_GRT  =  6            ; frames between glitter patterns
TT_SUNX =  HP_MAP+136   ; the sun's left edge (P/M): its centre is
                        ; colour clock 140, MKTITLE.PY's SUN_X
TT_HPM  =  [32+TT_HORL]/2 ; the horizon's double-line P/M line (the
                        ; picture starts at scan line 32)
TT_SUN0 =  TT_HPM-6     ; the sun's first P/M line at the start: 12 of
                        ; its 16 scan lines above the horizon
TT_P3   =  PM_P0+[3*PM_LEN] ; player 3's memory: the sun
C_SUN   =  $1E          ; the sun (COLPM3, set by TT_DLI)
C_TBRT  =  $1E          ; the bright glitter (COLPF3)
C_TSHD  =  $00          ; the island and the logo's shadow (COLPF2)

; ---------------------------------------------------------------------
;  TITLE_ENTER -- show the title screen.  Trashes A, X, Y.
; ---------------------------------------------------------------------
TITLE_ENTER
        JSR MUS_TITLE
        LDA #GS_TITLE
        STA GSTATE
        LDA #0
        STA TI_ARM
        STA TI_SEC
        STA TT_PRS      ; PRESS FIRE not shown yet
        STA TT_SFC      ; the sun sinks 256 frames from now
        STA TT_GFC      ; glitter at the first frame
        JSR PM_HIDE     ; no cursors, fish, weather or pirates
        JSR TIC_SYNC    ; idle time counts from now
        LDA #0          ; the water and prompt rows empty
        LDX #TT_PRSO+20
TE_CLR  DEX
        STA TT_SCR,X
        BNE TE_CLR
        LDA #TT_SUN0
        STA TT_SUN
        JSR TT_SUND     ; the sun in player 3
        JSR TT_GLIT     ; the first glitter
        LDA #>TTFONT    ; the scene's font, also the caption's letters
        STA CHBAS
        LDA TTP0        ; colours: the first line's, until TT_DLI sets
        STA COLOR0      ; each line's
        LDA TTP1
        STA COLOR1
        LDA #C_TSHD
        STA COLOR2
        LDA #C_TBRT
        STA COLOR3
        LDA TTBK
        STA COLOR4
        LDA #<TDLIST    ; same page as DLIST: one store switches
        STA SDLSTL
        RTS

; ---------------------------------------------------------------------
;  TITLE_FRAME -- each frame of the title screen: once everything is
;  let go, fire, START or any key goes on to the setup screen; after
;  DM_IDLE seconds with nothing touched, the demo.  Trashes A, X, Y.
; ---------------------------------------------------------------------
TITLE_FRAME
        LDA JOY0        ; anything touched: idle time from 0
        ORA JOY1
        ORA FIRE0
        ORA FIRE1
        ORA KEYDOWN
        ORA CONKEY
        BEQ TF_IDLE
        LDA #0
        STA TI_SEC
TF_IDLE JSR TIC_POLL    ; count the idle seconds
TF_TIC  JSR TIC_NEXT
        BCC TF_TDON
        BNE TF_TIC      ; not a new second
        INC TI_SEC
        BNE TF_TIC
TF_TDON JSR TT_ANIM     ; the sun, the glitter, the prompt
        LDA TI_SEC
        CMP #DM_IDLE
        BCC TF_KEYS
        JSR TT_LEAVE
        JMP DEMO_GO
TF_KEYS LDA FIRE0
        ORA FIRE1
        ORA KEYDOWN
        ORA CONKEY
        LDX TI_ARM
        BNE TF_ARMED
        CMP #0
        BNE TF_DONE     ; still held (OPTION at power-on, say)
        INC TI_ARM
TF_DONE RTS
TF_ARMED
        CMP #0
        BEQ TF_DONE
        JSR TT_LEAVE
        JMP SETUP_ENTER

; ---------------------------------------------------------------------
;  TT_ANIM -- each frame: PRESS FIRE once TI_SEC reaches TT_PSEC (it
;  stays up), the sun one P/M line lower every 256 frames until it has
;  set, new glitter every TT_GRT frames.  Trashes A, X, Y.
; ---------------------------------------------------------------------
TT_ANIM
        LDA TT_PRS
        BNE TA_SUN
        LDA TI_SEC
        CMP #TT_PSEC
        BCC TA_SUN
        INC TT_PRS
        LDX #19
TA_PRS  LDA TTPRS,X
        STA TT_SCR+TT_PRSO,X
        DEX
        BPL TA_PRS
TA_SUN  DEC TT_SFC
        BNE TA_GL
        LDA TT_SUN
        CMP #TT_HPM
        BCS TA_GL       ; set already
        INC TT_SUN
        JSR TT_SUND
TA_GL   DEC TT_GFC
        BPL TA_DONE
        LDA #TT_GRT-1
        STA TT_GFC
        JMP TT_GLIT
TA_DONE RTS

; ---------------------------------------------------------------------
;  TT_SUND -- draw the sun in player 3 from P/M line TT_SUN down, cut
;  off at the horizon (TT_HPM).  Trashes A, X, Y.
; ---------------------------------------------------------------------
TT_SUND
        JSR TT_LEAVE    ; player 3 empty
        LDX TT_SUN
        LDY #0
TV_ROW  CPX #TT_HPM
        BCS TV_DONE     ; under the horizon: hidden
        LDA TT_SUNS,Y
        STA TT_P3,X
        INX
        INY
        CPY #8
        BNE TV_ROW
TV_DONE RTS

TT_SUNS .BYTE $3C,$7E,$FF,$FF,$FF,$FF,$7E,$3C   ; 8 x 16 scan lines

; ---------------------------------------------------------------------
;  TT_LEAVE -- player 3 empty again (the sun off), before the title
;  screen hands over: the fish use player 3.  Trashes A, X.
; ---------------------------------------------------------------------
TT_LEAVE
        LDA #0
        LDX #PM_LEN-1
TL_CLR  STA TT_P3,X
        DEX
        BPL TL_CLR
        RTS

; ---------------------------------------------------------------------
;  TT_GLIT -- new glitter on the water: in each of the TT_WROWS rows,
;  TG_N gold glints (TG_SUN...) and one bright one (TG_BRT..., PF3)
;  within TG_W columns under the sun, widening down the rows, and two
;  dim reflections of the sky (TG_SKY...) anywhere.  Trashes A, X, Y,
;  TT_N.
; ---------------------------------------------------------------------
TT_GLIT
        LDA #0
        LDX #40*TT_WROWS
TG_CLR  DEX
        STA TT_SCR,X
        BNE TG_CLR
        LDY #0          ; Y: the row
TG_ROW  LDA TG_N,Y
        STA TT_N
TG_GOLD LDA TG_W,Y      ; a gold glint under the sun
        JSR RAND_N
        CLC
        ADC TG_X0,Y
        TAX
        LDA #TG_NSUN
        JSR RAND_N
        CLC
        ADC #TG_SUN
        STA TT_SCR,X
        DEC TT_N
        BNE TG_GOLD
        LDA TG_W,Y      ; and a bright one
        JSR RAND_N
        CLC
        ADC TG_X0,Y
        TAX
        LDA #TG_NBRT
        JSR RAND_N
        CLC
        ADC #TG_BRT+$80 ; inverse: its 11 pixels are PF3
        STA TT_SCR,X
        LDA #2          ; two reflections of the sky, anywhere
        STA TT_N
TG_SKYL LDA #40
        JSR RAND_N
        CLC
        ADC TG_R0,Y
        TAX
        LDA #TG_NSKY
        JSR RAND_N
        CLC
        ADC #TG_SKY
        STA TT_SCR,X
        DEC TT_N
        BNE TG_SKYL
        INY
        CPY #TT_WROWS
        BNE TG_ROW
        RTS

; per water row (TT_WROWS = 3): gold glints, columns wide, first column
TG_N    .BYTE 2,3,4
TG_W    .BYTE 3,5,7
TG_X0   .BYTE TT_SCOL-1,40+TT_SCOL-2,80+TT_SCOL-3
TG_R0   .BYTE 0,40,80

; ---------------------------------------------------------------------
;  TT_DLI -- the DLI on TDLIST's last blank line: the sun's position
;  and colour, then COLBK, COLPF0 and COLPF1 for every pair of scan
;  lines of the picture from TTBK, TTP0, TTP1 (TT_NL entries).  It runs
;  through the whole picture (192 lines); the title screen does little
;  else.  Keeps all registers.
; ---------------------------------------------------------------------
TT_DLI
        PHA
        TXA
        PHA
        TYA
        PHA
        LDA #TT_SUNX    ; the sun: player 3 (VBI_D hides it each frame)
        STA HPOSP3
        LDA #C_SUN
        STA COLPM3
        LDX #0
TD_LINE LDA TTBK,X
        LDY TTP0,X
        STA WSYNC       ; at the end of a line: its colours for the
        STA COLBK       ; next two
        STY COLPF0
        LDA TTP1,X
        STA COLPF1
        STA WSYNC
        INX
        CPX #TT_NL
        BNE TD_LINE
        PLA
        TAY
        PLA
        TAX
        PLA
        RTI
